import { test, expect } from '@playwright/test';

test('user can reset password with a valid link', async ({ page }) => {
  await page.goto('/login');
  await page.getByRole('link', { name: 'Forgot password?' }).click();

  await page.getByLabel('Email').fill('qa.user@example.com');
  await page.getByRole('button', { name: 'Send reset link' }).click();

  await expect(page.getByText('Check your email')).toBeVisible();

  // Simulate following the reset link from the email
  await page.goto('/reset-password?token=test-token-123');
  await page.getByLabel('New password').fill('N3wPassword!23');
  await page.getByLabel('Confirm password').fill('N3wPassword!23');
  await page.getByRole('button', { name: 'Update password' }).click();

  await expect(page.getByText('Password updated')).toBeVisible();
  await expect(page).toHaveURL('/login');
});
